Lemma rpres_except_entry st lo (sp : word) m m1 :
  munch [(bv_unsigned sp - 96, bv_unsigned sp)]%Z m m1 -> wmono rsegs m m1 -> lo <= bv_unsigned sp - 96 ->
  rpres_except (rfree_fp st lo (bv_unsigned sp)) m m1.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 5 "SH0!1,3|600;!1+20|30;%~R1!1+4!1+2!1,32!2+7+1+1!2':0#3!1,;|620;!1,<4!2':0#6!3'A#8#78!3,64!4,8+1+1!2'98687!2':0#7!2+C!2'?!2'9;6#1!2'D#1;!2':0#8}1!1+R+1|11;!2,Z+1@!3,Y+1A!2,[+16|10;!2,Z+1C!7,W?'S+T+T,U!4,X+1D,^1A,^0!1,^2+T!2,Z+1,^3$st;R+0$lo;R+1$sp;R1$m;R3$m1;R3$MU;R!3'5!3,64!4,8+1+1!2'95657#2#1$WM;R!3'='>#3#2$LOLE;R!2'?#6!2'9!2':0#56&MU;R!7'@9:#5#4#3#2vd!4,B%x;R+1%~R<!4'A#:#9=#2+E$x;R+1$Hx;R<!5'F#:#9=#2&__arith;R$__x3;R+1$__x2;R+1$__x1;R+1&__wit;R!3,6+G!2,H!3,I+1!2,J+1}3!3,I+1!2,J+1>!2,J+1,K,L!1,<+G!1+M+G&__varmap;R!4,N+1!2,O+1#3#2!2,O+1#4!1+P+1&__ff;R!8,Q?'S+T+T,U!7,V?'S+T+T,U!7,W?'S+T+T,U!4,X+1B,\D,^0EF!8,Q?'S+T+T,U!7,W?'S+T+T,U!4,X+1G,\B,^0F!7,V?'S+T+T,U!7,W?'S+T+T,U!4,X+1G,\D,^0E!2'^4?,U!4'^5#1#3vv!2,^6+^7,^8!3+^9+^7!2'^:#1#3,^8!3'^;+1,^<#2%__x3;R+1%__x2;R+1%__x1;R+1%~R!2+C!2'?!2'9#36#2!2'D#2#3%~R!2'?#2!2'9#46!2+C!2'?#3#4!2'D#4#5!5#1!2':0#9#3#:#2#4,^=!2'^>9:!3'^?9#5#4#1").
