Lemma rfree_fp_frame st st' lo (sp sp' : Z) a : ntf_frame st st' -> sp' <= sp -> rfree_fp st' lo sp' a -> rfree_fp st lo sp a.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 6 "S00$st;R+0$st';R+0$lo;R+1$sp;R+1$sp';R+1$a;R+1$FR;R!2+`F#6#5$HS;R!2'?#3#4$H;R!4'A#7#6#4#3!;'`G#9#8#7#6#5#4!3'`H#9#8#3!3'`I#9#8#3!3'`J#9#8#3#2#1").
Qed.

